/* config.h - hand maintained for the Qt6 port.
 *
 * The original file was generated by autoconf and then edited for Windows.
 * It is now platform conditional so the same tree builds on Windows (MinGW)
 * and on Linux/other POSIX systems.
 */
#define HAVE_FCNTL_H 1
#define HAVE_LIMITS_H 1
#define HAVE_LIBDSK_H 0
#define HAVE_SYS_TYPES_H 1
#define HAVE_SYS_STAT_H 1

#ifdef _WIN32
/* Original Windows settings (neko Java 2023.04.25) */
#define HAVE_UNISTD_H 0
#define HAVE_WINDOWS_H 1
#define HAVE_WINIOCTL_H 1
#define HAVE_MODE_T 0
#else
/* POSIX systems provide these directly. */
#define HAVE_UNISTD_H 1
#define HAVE_WINDOWS_H 0
#define HAVE_WINIOCTL_H 0
#define HAVE_MODE_T 1
#endif

#if HAVE_SYS_STAT_H
#include <sys/stat.h>
#endif

#if HAVE_SYS_TYPES_H
#include <sys/types.h>
#endif

#if HAVE_LIMITS_H
#include <limits.h>
#endif

#if HAVE_UNISTD_H
#include <unistd.h>
#else              // add neko Java 2023.04.30
#include <io.h>    // add neko Java 2023.04.30
#endif

#if HAVE_WINDOWS_H
#include <windows.h>
#endif

#if HAVE_WINIOCTL_H
#include <winioctl.h>
#endif

#if HAVE_LIBDSK_H
#include <libdsk.h>
#endif

#if HAVE_FCNTL_H
#include <fcntl.h>
#endif

#ifndef _POSIX_PATH_MAX
#ifdef _WIN32
#define _POSIX_PATH_MAX _MAX_PATH
#else
#define _POSIX_PATH_MAX 4096
#endif
#endif

#include <time.h>

